1	import { request } from 'node:https';
2	import { createHash } from 'node:crypto';
3	import { mkdir, open, readFile, rename } from 'node:fs/promises';
4	import { join } from 'pathe';
5	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
6	import {
7		AcquisitionFailure,
8		canonicalResponseRecord,
9		exactRequestUrl,
10		responseRecord,
11		type AcquisitionObservation,
12		type AcquisitionState,
13		type DurableResponseRecord,
14		type ExactRequestDescriptor,
15	} from '../../../core/src/acquisition/transaction.ts';
16	
17	export type AcquisitionTransaction = Readonly<{
18		consentId: string;
19		durableRoot: string;
20		metadataCap: number;
21		archiveCap: number;
22		aggregateCap: number;
23	}>;
24	
25	const fsyncDirectory = async (directory: string): Promise<void> => {
26		const handle = await open(directory, 'r');
27		try {
28			await handle.sync();
29		} finally {
30			await handle.close();
31		}
32	};
33	
34	export async function persistAcceptedResponse(
35		transaction: AcquisitionTransaction,
36		descriptor: ExactRequestDescriptor,
37		state: AcquisitionState,
38		body: Buffer,
39	): Promise<DurableResponseRecord> {
40		await mkdir(transaction.durableRoot, { recursive: true });
41		const record = responseRecord(descriptor, state.acceptedResponses + 1, body);
42		const bodyPath = join(transaction.durableRoot, record.bodyFile);
43		const partialPath = `${bodyPath}.partial`;
44		const bodyHandle = await open(partialPath, 'wx');
45		try {
46			await bodyHandle.writeFile(body);
47			await bodyHandle.sync();
48		} finally {
49			await bodyHandle.close();
50		}
51		await rename(partialPath, bodyPath);
52		await fsyncDirectory(transaction.durableRoot);
53		const journal = await open(join(transaction.durableRoot, 'journal.ndjson'), 'a');
54		try {
55			await journal.writeFile(`${canonicalResponseRecord(record)}\n`);
56			await journal.sync();
57		} finally {
58			await journal.close();
59		}
60		return record;
61	}
62	
63	export async function acquireExactResponse(
64		transaction: AcquisitionTransaction,
65		descriptor: ExactRequestDescriptor,
66		state: AcquisitionState,
67	): Promise<Buffer> {
68		const url = exactRequestUrl(descriptor);
69		const cap =
70			descriptor.responseKind === 'archive' ? transaction.archiveCap : transaction.metadataCap;
71		for (let attempt = 1; attempt <= 3; attempt += 1) {
72			try {
73				return await new Promise<Buffer>((resolvePromise, reject) => {
74					let responseObserved = false;
75					const call = request(
76						url,
77						{
78							method: 'GET',
79							headers: {
80								accept:
81									descriptor.responseKind === 'json'
82										? 'application/vnd.github+json'
83										: 'application/octet-stream',
84								'accept-encoding': 'identity',
85								'user-agent': 'versionless-shared-acquisition',
86								'x-versionless-consent-id': transaction.consentId,
87							},
88						},
89						(response) => {
90							responseObserved = true;
91							const observation: AcquisitionObservation = {
92								method: 'GET',
93								url,
94								purpose: descriptor.purpose,
95								attempt,
96								status: response.statusCode ?? 0,
97								headersObserved: true,
98								bodyBytes: 0,
99								acceptedResponse: false,
100							};
101							state.observations.push(observation);
102							if (response.statusCode !== 200) {
103								response.destroy();
104								reject(
105									new AcquisitionFailure(
106										'transport',
107										response.statusCode &&
108											response.statusCode >= 300 &&
109											response.statusCode < 400
110											? 'redirect-status'
111											: 'non-200-status',
112										200,
113										response.statusCode ?? 0,
114										'Acquisition response status differs',
115									),
116								);
117								return;
118							}
119							if ((response.headers['content-encoding'] ?? 'identity') !== 'identity') {
120								response.destroy();
121								reject(
122									new AcquisitionFailure(
123										'transport',
124										'content-encoding',
125										'identity',
126										'non-identity',
127										'Acquisition content encoding differs',
128									),
129								);
130								return;
131							}
132							let bytes = 0;
133							const chunks: Buffer[] = [];
134							response.on('data', (chunk: Buffer) => {
135								bytes += chunk.byteLength;
136								(observation as { bodyBytes: number }).bodyBytes = bytes;
137								if (
138									bytes > cap ||
139									state.aggregateBytes + bytes > transaction.aggregateCap
140								)
141									response.destroy(
142										new AcquisitionFailure(
