// Baseline install/build attempt for the admitted candidate, inside its declared legacy cell.
// Truthful outcome recording: a failing install or build is recorded, not repaired.
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';

const slug = process.argv[2];
const root = join(new URL('.', import.meta.url).pathname, '../../..');
const evidenceDir = join(root, 'evidence/ingests', slug);
const cell = join(root, '.versionless/cache/node16');
const work = join(root, '.versionless/work', slug, 'legacy');
const npmCache = join(root, '.versionless/cache/npm-cache');
const sha256 = (b) => createHash('sha256').update(b).digest('hex');

const env = {
	...process.env,
	PATH: `${join(cell, 'bin')}:${process.env.PATH ?? ''}`,
	npm_config_cache: npmCache,
	NPM_CONFIG_CACHE: npmCache,
	CI: 'true',
};
const nodeBin = join(cell, 'bin/node');
const npmBin = join(cell, 'bin/npm');

function step(name, args) {
	const startedAt = new Date().toISOString();
	const started = Date.now();
	const result = spawnSync(npmBin, args, { cwd: work, env, encoding: 'utf8', maxBuffer: 1 << 28 });
	const stdout = result.stdout ?? '';
	const stderr = result.stderr ?? '';
	const tail = (text) => text.split('\n').slice(-40).join('\n').trim();
	return {
		name,
		command: `npm ${args.join(' ')}`,
		startedAt,
		durationMs: Date.now() - started,
		exitCode: result.status,
		signal: result.signal ?? null,
		outcome: result.status === 0 ? 'succeeded' : 'failed',
		stdoutBytes: Buffer.byteLength(stdout),
		stderrBytes: Buffer.byteLength(stderr),
		stdoutSha256: sha256(Buffer.from(stdout)),
		stderrSha256: sha256(Buffer.from(stderr)),
		stdoutTail: tail(stdout),
		stderrTail: tail(stderr),
	};
}

const nodeVersion = spawnSync(nodeBin, ['--version'], { encoding: 'utf8' }).stdout.trim();
const npmVersion = spawnSync(npmBin, ['--version'], { env, encoding: 'utf8' }).stdout.trim();
const install = step('install', ['ci', '--ignore-scripts', '--no-audit', '--no-fund']);
const build = install.exitCode === 0 ? step('build', ['run', 'build']) : null;

const buildDir = join(work, 'build');
let artifacts = null;
if (existsSync(buildDir)) {
	const files = [];
	const walk = (dir) => {
		for (const entry of readdirSync(dir, { withFileTypes: true })) {
			const full = join(dir, entry.name);
			if (entry.isDirectory()) walk(full);
			else if (entry.isFile()) files.push(full);
		}
	};
	walk(buildDir);
	artifacts = {
		root: relative(root, buildDir),
		files: files.length,
		bytes: files.reduce((total, file) => total + statSync(file).size, 0),
		manifestSha256: sha256(
			Buffer.from(
				`${files
					.map((file) => `${relative(buildDir, file)} ${sha256(readFileSync(file))}`)
					.sort()
					.join('\n')}\n`,
			),
		),
	};
}

const record = {
	schemaVersion: 'versionless.legacy-baseline-attempt.v1',
	slug,
	cell: {
		node: nodeVersion,
		npm: npmVersion,
		platform: `${process.platform}-${process.arch}`,
		lifecycleScripts: 'disabled for install (--ignore-scripts)',
		network: 'npm registry reachable during the consented acquisition window only',
	},
	workRoot: relative(root, work),
	steps: build ? [install, build] : [install],
	outcome: build ? build.outcome : install.outcome,
	artifacts,
	nonclaims: [
		'A recorded install or build outcome establishes no browser behavior, journey coverage, migration feasibility, pilot status, or production readiness.',
		'A failing step is recorded as observed; no repair, pin, or flag was applied to make it pass.',
	],
};
writeFileSync(join(evidenceDir, 'baseline-attempt.json'), `${JSON.stringify(record, null, 2)}\n`);
console.log(JSON.stringify({ outcome: record.outcome, steps: record.steps.map((s) => [s.name, s.exitCode]) }));

