// Dependency closure with honest lock state, derived offline from the verified source archive.
// No repair, no re-resolution: what the committed lockfile states is what is recorded.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';

const [slug, sourceRootArg, frontend] = process.argv.slice(2);
const root = join(new URL('.', import.meta.url).pathname, '../../..');
const sourceRoot = join(root, sourceRootArg);
const appRoot = join(sourceRoot, frontend);
const sha256 = (b) => createHash('sha256').update(b).digest('hex');

const packageBytes = readFileSync(join(appRoot, 'package.json'));
const lockBytes = readFileSync(join(appRoot, 'package-lock.json'));
const manifest = JSON.parse(packageBytes.toString());
const lock = JSON.parse(lockBytes.toString());

const entries = [];
const hosts = new Map();
const walk = (dependencies, path) => {
	for (const [name, value] of Object.entries(dependencies ?? {})) {
		const record = {
			name,
			version: value.version,
			path: [...path, name].join('/'),
			resolved: value.resolved ?? null,
			integrity: value.integrity ?? null,
			dev: value.dev === true,
			optional: value.optional === true,
			bundled: value.bundled === true,
		};
		entries.push(record);
		if (record.resolved) {
			const host = new URL(record.resolved).host;
			hosts.set(host, (hosts.get(host) ?? 0) + 1);
		}
		walk(value.dependencies, [...path, name]);
	}
};
walk(lock.dependencies, []);

const declared = Object.keys(manifest.dependencies ?? {}).length;
const declaredDev = Object.keys(manifest.devDependencies ?? {}).length;
const withoutResolved = entries.filter((e) => !e.resolved && !e.bundled);
const withoutIntegrity = entries.filter((e) => !e.integrity && !e.bundled);
const distinct = new Set(entries.map((e) => `${e.name}@${e.version}`));

const record = {
	schemaVersion: 'versionless.legacy-dependency-closure.v1',
	slug,
	frontendRoot: frontend,
	source: {
		verifiedSourceRoot: relative(root, sourceRoot),
		packageJsonSha256: sha256(packageBytes),
		packageLockSha256: sha256(lockBytes),
		packageLockBytes: lockBytes.byteLength,
	},
	lockState: {
		file: 'package-lock.json',
		lockfileVersion: lock.lockfileVersion ?? null,
		requiresField: lock.requires ?? null,
		committedWithSource: true,
		coversDevDependencies: entries.some((e) => e.dev),
		everyEntryHasResolvedUrl: withoutResolved.length === 0,
		everyEntryHasIntegrityHash: withoutIntegrity.length === 0,
		entriesWithoutResolvedUrl: withoutResolved.map((e) => e.path),
		entriesWithoutIntegrityHash: withoutIntegrity.map((e) => e.path),
		lockfileIntegrityAlgorithms: [
			...new Set(entries.map((e) => (e.integrity ?? 'none').split('-')[0])),
		].sort(),
	},
	counts: {
		declaredDependencies: declared,
		declaredDevDependencies: declaredDev,
		lockedPlacements: entries.length,
		distinctNameVersionPairs: distinct.size,
		devPlacements: entries.filter((e) => e.dev).length,
		optionalPlacements: entries.filter((e) => e.optional).length,
		bundledPlacements: entries.filter((e) => e.bundled).length,
	},
	registryHosts: Object.fromEntries([...hosts].sort()),
	closureSha256: sha256(
		Buffer.from(
			`${entries
				.map((e) => `${e.path} ${e.version} ${e.integrity ?? 'none'}`)
				.sort()
				.join('\n')}\n`,
		),
	),
	nonclaims: [
		'Per-artifact byte digests were not independently mirrored in this unit; the recorded integrity hashes are the ones the committed lockfile declares.',
		'A resolvable closure establishes no build, browser behavior, licence compatibility of transitive dependencies, migration feasibility, or production readiness.',
	],
};
writeFileSync(
	join(root, 'evidence/ingests', slug, 'closure.json'),
	`${JSON.stringify(record, null, 2)}\n`,
);
console.log(JSON.stringify({ ...record.counts, ...record.lockState.lockfileVersion }, null, 1));
console.log(JSON.stringify(record.lockState.lockfileVersion));
console.log(JSON.stringify(record.registryHosts));

